// MT2009_PLUS_MALL_STACK_V1 (stale rows) (server-patches/mall3): an item taken out of the
// item-shop storage is saved into the item cache (window INVENTORY, owner the player);
// its table row says MALL until the cache is flushed. A MALL row is never cached
// (QUERY_ITEM_SAVE writes it and drops the cache entry), so a row whose id is in the
// cache is not in the storage: it is not sent, or the game would show it twice and its
// stack merge (LoadMall) could pour units that are already in the bag.
if (pi->ip[0] == 1)
{
	size_t kept = 0;
	for (size_t i = 0; i < s_items.size(); ++i)
	{
		if (GetItemCache(s_items[i].id))
		{
			sys_log(0, "MALL: item %u (vnum %u) of account %u is in the item cache - not in the storage",
					s_items[i].id, s_items[i].vnum, pi->account_id);
			continue;
		}
		s_items[kept++] = s_items[i];
	}
	s_items.resize(kept);
}

pi->pSafebox->wItemCount = s_items.size();
